targets.query:
WITH latest_system AS (
  SELECT time, hostname, device_ip, vendor, platform, device_role, uptime_ticks, customer, site,
         ROW_NUMBER() OVER (PARTITION BY hostname ORDER BY time DESC) AS rn
  FROM fortigate_system
  WHERE time >= now() - INTERVAL ${time_range:sqlstring}
    AND customer_id LIKE ${customer:sqlstring}
    AND site_id LIKE ${site:sqlstring}
    AND hostname LIKE ${device:sqlstring}
), latest_performance AS (
  SELECT time, hostname, firmware,
         ROW_NUMBER() OVER (PARTITION BY hostname ORDER BY time DESC) AS rn
  FROM fortigate_performance
  WHERE time >= now() - INTERVAL ${time_range:sqlstring}
    AND customer_id LIKE ${customer:sqlstring}
    AND site_id LIKE ${site:sqlstring}
    AND hostname LIKE ${device:sqlstring}
)
SELECT s.hostname, 'Not collected' AS model, 'Not collected' AS serial, p.firmware, 'Not collected' AS build,
       s.uptime_ticks / 100.0 AS uptime_seconds, s.customer, s.site, 'telegraf-snmp' AS collector,
       CASE WHEN p.time > s.time THEN p.time ELSE s.time END AS last_collection_time,
       s.device_ip, s.vendor, s.platform, s.device_role
FROM latest_system s
LEFT JOIN latest_performance p ON s.hostname = p.hostname AND p.rn = 1
WHERE s.rn = 1
ORDER BY s.hostname

