targets.query:
SELECT time AS last_successful_run, duration_ms AS duration, api_requests, points_written, retry_count AS retries, error_count AS errors
FROM collector_health
WHERE time >= now() - INTERVAL ${time_range:sqlstring}
  AND collector IN ('fortigate', 'snmp')
  AND customer_id LIKE ${customer:sqlstring}
  AND site_id LIKE ${site:sqlstring}
  AND success = true
ORDER BY time DESC
LIMIT 20

